<section class="page-heading"><span class="eyebrow">Personal information</span><h1>Your profile</h1><p>These optional details help compare your situation with scheme rules. Empty fields remain unknown, not “No”.</p></section><form method="post" class="form-card wide-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_profile"><div class="form-grid"><div class="field"><label for="name">Full name</label><input id="name" name="name" required maxlength="120" value="<?=e(current_user()['name'])?>"></div><div class="field"><label for="date_of_birth">Date of birth</label><input type="date" id="date_of_birth" name="date_of_birth" max="<?=date('Y-m-d')?>" value="<?=e($profile['date_of_birth']??'')?>"><small>Used to calculate age for applicable rules.</small></div><div class="field"><label for="annual_income">Annual family income (₹)</label><input type="number" min="0" step="0.01" id="annual_income" name="annual_income" value="<?=e($profile['annual_income']??'')?>"><small>Used only when a scheme defines an income condition.</small></div><div class="field"><label for="state">State or union territory</label><input id="state" name="state" maxlength="80" value="<?=e($profile['state']??'')?>"></div><div class="field"><label for="occupation">Occupation</label><select id="occupation" name="occupation"><option value="">Prefer not to say / not provided</option><?php foreach(['Student','Employed','Self-employed','Unemployed','Farmer','Other'] as $v): ?><option <?=$profile['occupation']===$v?'selected':''?>><?=e($v)?></option><?php endforeach; ?></select></div><div class="field"><label for="education">Education level</label><input id="education" name="education" maxlength="80" value="<?=e($profile['education']??'')?>"></div><div class="field"><label for="gender">Gender <span class="optional">optional</span></label><input id="gender" name="gender" maxlength="40" value="<?=e($profile['gender']??'')?>"></div><div class="field"><label for="social_category">Social category <span class="optional">optional</span></label><input id="social_category" name="social_category" maxlength="40" value="<?=e($profile['social_category']??'')?>"></div><div class="field"><label for="residence_type">Residence</label><select id="residence_type" name="residence_type"><option value="">Not provided</option><option value="rural" <?=($profile['residence_type']??'')==='rural'?'selected':''?>>Rural</option><option value="urban" <?=($profile['residence_type']??'')==='urban'?'selected':''?>>Urban</option></select></div><div class="field"><label for="disability_status">Disability status <span class="optional">optional</span></label><select id="disability_status" name="disability_status"><option value="">Not provided</option><option value="1" <?=isset($profile['disability_status'])&&$profile['disability_status']==1?'selected':''?>>Yes</option><option value="0" <?=isset($profile['disability_status'])&&$profile['disability_status']==0?'selected':''?>>No</option></select></div></div><div class="form-actions"><button class="button" type="submit">Save profile</button><a class="button button-outline" href="<?=e(url('dashboard'))?>">Cancel</a></div></form>
